import RenderRouter from "./routes";
import { BrowserRouter as Router } from "react-router-dom";
import { ConfigProvider, Spin, theme as a } from "antd";
import Loading from "components/elements/Loading";
import { useGlobalAppStore } from "store/useGlobalApp";
import { useEffect } from "react";
import { useTranslation } from "react-i18next";
import requestService from "api/request";
function App() {
  const { loading, handleSetConfig } = useGlobalAppStore()
  const { t, i18n } = useTranslation();

  const getConfigApp = async () => {
    try {
      const res = await requestService.get('/config')
      if (res && res.data) {
        handleSetConfig(res?.data?.data)
      }
    } catch (error) {
      console.log('====================================');
      console.log(error);
      console.log('====================================');
    }
  }

  useEffect(() => {
    getConfigApp()
  }, [])

  useEffect(() => {
    if (localStorage.getItem('lang')) {
      i18n.changeLanguage(localStorage.getItem('lang') || "vi");
    }
    else {
      i18n.changeLanguage('en')
    }
  }, [])


  useEffect(() => {
    window.$crisp = [];
    window.CRISP_WEBSITE_ID = "55c95755-e70a-4ef9-b2f5-cbcb75676280";

    (function () {
      const d = document;
      const s = d.createElement("script");
      s.src = "https://client.crisp.chat/l.js";
      s.async = true;
      d.getElementsByTagName("head")[0].appendChild(s);
    })();
  }, []);

  return (
    <ConfigProvider>
      {
        loading && <Loading />
      }

      <Router>
        <RenderRouter />
      </Router>
    </ConfigProvider>
  );
}

export default App;
